def mark_old_runs(apps, schema_editor):
    """Runs made before Task 76 used min-max scaling and read their weights live from the AHP run: label them and
    copy those weights in, so later weight edits never change how they read. Their scores are not recomputed."""
    Run = apps.get_model("decision_support", "FundingRecommendationRun")
    for run in Run.objects.select_related("ahp_run").prefetch_related("ahp_run__criteria"):
        run.method = "minmax_v1"
        run.weights_snapshot = dict(run.ahp_run.weights)
        run.formulas_snapshot = {
            str(c.id): {"metric_key": c.metric_key, "mode": "standard"} for c in run.ahp_run.criteria.all()
        }
        run.save(update_fields=["method", "weights_snapshot", "formulas_snapshot"])


